{"args":{"content":""""The one shared counter. Every read and change goes through a single lock."""

import threading


class Counter:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    def read(self):
        with self._lock:
            return self._value

    def increment(self):
        with self._lock:
            self._value += 1
            return self._value

    def reset(self, value):
        with self._lock:
            self._value = value
